"""Self-contained scientific handoff, using frozen results only."""
import csv,json,pathlib
BASE=pathlib.Path(__file__).resolve().parents[1];OUT=BASE/'outputs/PMFS_R3_R5_CONTINUOUS_20261011'
def main():
    d=json.loads((OUT/'R4_DECISION.json').read_text());r3=json.loads((OUT/'R3_SUMMARY.json').read_text());test=json.loads((OUT/'R4_HELDOUT_SUMMARY.json').read_text());receipt=json.loads((OUT/'R4_BATCH_RECEIPT.json').read_text());m=d['selected_ordinary'];s=test[m]
    rows=list(csv.DictReader((OUT/'R4_PER_TASK_HOLDOOUT.csv').open(encoding='utf-8')));f=[r for r in rows if r['events']=='50'];correct={method:sum(float(r['main_distance_m'])==0 for r in f if r['method']==method) for method in test}
    text=f'''# 给 Pro 的 R3→R4→条件 R5 完整交接\n\n## 本轮已经做完什么\n\n直接人类授权“按合同连续执行”。在隔离分支执行只读R3、预注册36个动态数学任务（18开发、18未见源/具体风历史）与25个候选源完整对比，完成B0/B1/B2及wind oracle。没有新CFD/GADEN、ROS导航、GPU或模型训练，没有扩大任务、调阈值或重选seed。旧R2/E3/B4结论与原始证据不动。\n\n判决：WIND_STATIC_GAP={d['WIND_STATIC_GAP']}；ORDINARY_BASELINE_SUFFICIENT={d['ORDINARY_BASELINE_SUFFICIENT']}；R5={d['R5']}。这是已经执行后的条件停止分支，不是因为“又缺旧文件”而HOLD。真实三维/湖岸与原创算法资格仍未取得。\n\n## 一、R2为什么源概率改善而坐标确认失败\n\n六份已经查看过的R2任务，O1−O0平均：源NLL −1.268839，官方Top5距离 +0.091417m，MAP +0.318664m，完整均值 −0.662560m；原确认FAIL保留。真源增加不保证错误候选增加更小。Z04远处错误密度峰跨区域胜出；并列格处理不能解释掉这个跨区转移。\n\n32个区域预测覆盖447合法格，但不是447个独立原子源预测；区域面积先验与格内均匀回填在单格密度排序中抵消，不能仅归因面积。原生Top5、区域最大质量与最大格密度选的对象不同。\n\n同一已冻结后验、同一447格支持下，普通Euclidean风险medoid六任务均值：O0 2.125561m→O1 1.810222m。这说明一部分“概率改善却坐标不改善”依赖决策损失；并不使原官方确认通过。Z04该共同风险动作仍从1.903943m退化到2.304886m，所以不是换动作就都修好。\n\n连续浓度含二值读出丢掉的幅值源信息：Z04/Z05，真实源在均值幅值RMSE排名第一，但二值指标偏向错误候选。没有事前合格连续似然标定，因此仅探索性证据，不是新方法性能。两随机参考和粗区域也限制可辨识性结论。所有32源与六例反例均交付。\n\n## 二、新动态任务是否支持学习记忆的必要性\n\n全部源/风/路线/噪声/损失与判门在新数据出现前冻结。原初版seed存在跨任务流碰撞，生成数据前按不改变科学参数的技术修复生成REV1；原版保留，实际252流seed唯一。独立OU释放、OU风扰动及测量噪声使两个realization不是确定性曲线重复。\n\n12×12m、24×24周期FV，100s持续释放、50个事件，三种均风历史：constant/slow/fast，Tw/Tadv=∞/3.5/0.7。源与候选都在相同25点支持；单位mg/m³固定1m厚层，不能称ppm或真实PID。周期持续注入没有有限稳态，B0是固定初始风的连续瞬态近似。\n\nB1保存浓度历史并用因果local-wind滤波；B2联合风/释放/浓度不确定性。所有部署方法只看同一局地风与气体事件；风oracle单独读真实风。使用正确删失Gaussian似然，每事件只算一次，二值不当第二份观测。算法消费文件无真源；评估仅在输出冻结后读取真值。\n\n| 未见18任务方法 | 共同主距离m | 判对离散源点 | 源NLL | 90%覆盖 | 预测CRPS mg/m³ | 方法墙钟s/任务 |\n|---|---:|---:|---:|---:|---:|---:|\n'''
    for method,v in test.items():text+=f"|{method}|{v['main_distance_m']:.6f}|{correct[method]}/18|{v['source_NLL']:.6f}|{v['coverage90']:.3f}|{v['raw_predictive_CRPS']:.6f}|{v['method_wall_s']:.3f}|\n"
    text+=f'''\n开发集按事前主距离规则选 {m}，没有拟合参数，未见任务只评估一次。动态开发B0−B1平均距离 {d['dynamic_development_B0_minus_B1_m']:.6f}m；动态未见任务 {d['dynamic_heldout_B0_minus_B1_m']:.6f}m；恒定均风对照 {d['constant_negative_control_B0_minus_B1_m']:.6f}m。各源×风×realization与20/35/50前缀全部CSV保留，不能把50帧当50次独立实验。\n\n批次实际墙钟 {receipt['wall_s']:.2f}s，峰值RSS {receipt['peak_RSS_bytes']/2**20:.2f}MiB。完整36任务未追加第二批；R5未训练。\n\n## 三、这次证据能与不能说明什么\n\n可说明：在相同原子源支持和观测预算下，固定风历史近似会在注册变风条件下损害源推断；普通正确连续状态已经承载传播历史，并且本数值任务中无需新记忆网络即可达到预注册要求。\n\n不能说明：原生PMFS的B4错误收敛由时变风造成（B4观测期是静态CFD10）；R4不是新PMFS原生闭环；FV匹配求解器不是独立三维物理；候选点判对不是连续湖岸高精度。空间均匀风、周期回流、完整固定路线、源恰在候选点都是有利简化，未检验近源排除或真实空间风部分可观测性。\n\n有限24粒子与sinusoid+OU真风/random-walk估计的模型差异都公开记录；不把残差自动当历史记忆必要性。普通滤波已保留完整气体状态，FloWM视觉记忆不能仅凭它具有“历史”就超过此基线。在该均匀域，平移共享等常规优化还有先例，不能制造逐源计算瓶颈来主张新网络价值。\n\n## 四、文献边界与主创新判决\n\n已核验官方论文与源码：PMFS TRO2024；ADApprox IROS2025已知稳态风/稳态PDE；AMT2026已有动态浓度和源反演（固定滞后平滑含未来观测，不能当零延迟基线）；FloWM ICML2026是动态视觉空间记忆。RA-L2019 Active Localization of Gas Leaks using Fluid Simulation已经直接处理时变但空间均匀风及主动源定位。具体链接/原文与SHA在SOURCE_LITERATURE及literature目录。\n\n因此，本轮不推荐把“加入风历史、保存羽流、物理约束滤波”写成原创，也不推荐立即训练RPSPM。这不否定复杂湖岸存在更难的状态推断问题；它否定的是：仅凭现有静态R2与这组动态数学任务，已经证明复杂学习记忆有必要。可以撰写已有机制与基线工作，但尚不能开始宣称新算法有效的SCI主论文。\n\n## 五、希望你一次判断的三个问题\n\n1. 是否同意按冻结门结束RPSPM当前必要性假设，接受普通动态模型充分这一负研发结论，而不是为正结果改变风角/采样/阈值？\n2. 在已有R1/R2响应与候选源证据审计基础上，下一主创新应该面对“源间决策证据保真”还是“真实空间风部分可观测的输运条件”？请给需要超过的普通方法与最小可否证证据，不再只列网络名称。\n3. 若要研究真实部分可观测三维条件，怎样与已有动态Bayes/主动流体定位区别，并要求哪项受控物理证据才值得投入？当前不能用B4静态风或R4匹配求解器替代该证据。\n\n## 六、复核入口\n\n先读R4_MECHANISM_GO_NOGO和R3_MECHANISM_REPORT；独立verify_bundle.py不导入生产或评价函数，不运行仿真。核心包含全部432行端点及36任务全部后验/得分，16份完整预先指定候选预测用于逐事件似然复算；其他完整原始预测在RAW包与SHA清单。给出全部负结果与各层资格，不请你重复已完成的旧审计。\n'''
    (OUT/'PRO_FIRST_READ_zh.md').write_text(text,encoding='utf-8')
    (OUT/'00_直接发给Pro.txt').write_text('请先阅读核心包 PRO_FIRST_READ_zh.md。本轮已按你提供的R3→R4→条件性R5合同完成：R3复核旧六任务，R4预注册并运行36个动态数学任务与25源点完整基线；R5按普通基线充分性门停止，没有训练。请在证据边界内判断主创新必要性与下一最小物理问题，重点答PRO_FIRST_READ末尾三个问题，避免重复旧实验或仅推荐网络名称。完整指标、源码、原始预测、反例、独立核验和SHA都在包内；大RAW包可选。\n',encoding='utf-8')
if __name__=='__main__':main()
